const CLIENTS = {};
const clientKind = n => n === 'Розничный покупатель' ? 'розница' : /^ИП\s/.test(n) ? 'ИП' : /«|ООО|АО\b|ПАО|ЗАО/.test(n) ? 'юрлицо' : 'физлицо';
SALES.forEach(r => {
  const c = CLIENTS[r.client] || (CLIENTS[r.client] = { inn: r.inn, kind: clientKind(r.client), contacts: [] });
  if (r.contact.name !== '—' && !c.contacts.some(x => x.name === r.contact.name)) c.contacts.push({ ...r.contact });
});
